// Generated by build-last-smoke-demo.mjs from picks.json. Do not edit.
export const pick = (pool, rnd = Math.random, last = null) => {
  if (!pool?.length) return null;
  let i = Math.floor(rnd() * pool.length);
  if (pool.length > 1 && pool[i] === last) i = (i + 1) % pool.length;
  return pool[i];
};

